import sys; sys.path.insert(0,'/tmp/ss-build/tools/c10')
from lib10 import *
S='social-science'
def B(ch,cn,t,tn,*a,**k): build(S,ch,t,tn,*a,cname=cn,tname=tn,**k)
R="Both A and R are true and R explains A"
# H1
C,CN='hist-rise-of-nationalism-in-europe','History 1: The Rise of Nationalism in Europe'
B(C,CN,'rise-of-nationalism-in-europe','The Rise of Nationalism in Europe',
 "One flag, many kingdoms",
 "Imagine a map where your country does not exist yet, only dozens of small kingdoms. In the 1800s that was the map of Germany and Italy. Today we see how people came to feel they belonged to one nation.",
 [("In 1848 the French artist Frederic Sorrieu painted a dream of democratic and social republics, with people of Europe marching in groups with their national flags.","Sorrieu's vision"),
  ("The French Revolution of 1789 introduced ideas of la patrie, the citizen, a tricolour flag and an elected National Assembly. The idea of a nation of equal citizens spread.","French Revolution 1789"),
  ("Napoleon brought the Civil Code of 1804, also called the Napoleonic Code, which ended privileges by birth and made laws equal. It also removed customs barriers.","Napoleonic Code 1804"),
  ("After Napoleon's defeat, European powers met at Vienna in 1815 and restored conservative rule. Liberal nationalists wanted a constitution, freedom of the press and free markets.","Treaty of Vienna 1815"),
  ("Giuseppe Mazzini founded Young Italy in Marseilles and Young Europe in Berne. Revolutionaries in 1830 and 1848 pushed for national unity.","Mazzini"),
  ("Germany was united under Prussia, led by Otto von Bismarck and the army, in 1871. Wilhelm I was proclaimed German emperor at Versailles.","Germany 1871"),
  ("Italy was united through Cavour, Garibaldi's Red Shirts and the House of Sardinia-Piedmont under Victor Emmanuel II, who became king of united Italy in 1861.","Italy 1861"),
  ("In the Balkans, nationalist tensions and great-power rivalry made the region explosive and helped lead to the First World War.","Balkans")],
 ("Germany was united in 1871. How many years after the Treaty of Vienna (1815) was that?",[("Subtract the years.","1871 minus 1815."),("1871 - 1815 = 56 years.","Check 1815 + 56 = 1871.")]),
 ("Explain how nationalism led to the unification of Italy.",["Italy was divided into several states","Mazzini, Cavour and Garibaldi worked in different ways","Sardinia-Piedmont's king became king of Italy"],["Thinking Italy was united by a single battle"]),
 ["The French Revolution spread ideas of nation and citizen.","Napoleon's Code made laws equal but rule was imposed.","Germany (1871) and Italy (1861) were unified.","The Balkans were a source of conflict."],
 [mcq("h1-1",1,"Who founded Young Italy?","Giuseppe Mazzini",[("Garibaldi","Garibaldi led the Red Shirts."),("Cavour","Cavour was the chief minister of Sardinia-Piedmont.")],"Mazzini founded Young Italy in Marseilles."),
  tf("h1-2",1,"The Napoleonic Code of 1804 ended privileges based on birth.",True,"It made all citizens equal before the law."),
  mcq("h1-3",2,"Germany was united under the leadership of","Prussia",[("Austria","Austria was a rival."),("Bavaria","Not the leader.")],"Bismarck and the Prussian army led it."),
  num("h1-4",2,"In which year was Italy united under Victor Emmanuel II?",1861,"He became king of united Italy in 1861.",[(1871,"1871 is Germany.")]),
  mcq("h1-5",2,"Assertion (A): The Treaty of Vienna restored conservative rule. Reason (R): European powers wanted to undo changes made by Napoleon.",R,[("A true, R false","R explains the aim of 1815."),("A false, R true","A is correct.")],"Vienna 1815 restored monarchies."),
  short("h1-6",2,"Who painted the 1848 dream of democratic and social republics?",["sorrieu","frederic sorrieu"],"Sorrieu's prints showed people marching with flags.",[("delacroix","Not the artist of this series.")]),
  mcq("h1-7",3,"The Zollverein was a","customs union",[("secret society","Young Italy was one."),("parliament","The Frankfurt Parliament was one.")],"It abolished tariff barriers among German states from 1834."),
  tf("h1-8",3,"The Balkan region was peaceful and stable in the 1800s.",False,"Nationalist tension and great-power rivalry made it explosive.")])
# H2
C,CN='hist-nationalism-in-india','History 2: Nationalism in India'
B(C,CN,'nationalism-in-india','Nationalism in India',
 "A pinch of salt that shook an empire",
 "In 1930 a small, thin man walked for 24 days to a beach and picked up a pinch of salt. That act defied a mighty empire. We follow how Indians came together against British rule.",
 [("The First World War created new economic and political problems: heavy defence expenditure, price rise and forced recruitment of soldiers, so people were ready to protest.","effects of WWI"),
  ("Mahatma Gandhi returned from South Africa in 1915 and led satyagraha in Champaran, Kheda and Ahmedabad. In 1919 he called a nationwide satyagraha against the Rowlatt Act.","satyagraha"),
  ("On 13 April 1919 General Dyer's troops fired on a peaceful crowd at Jallianwala Bagh in Amritsar, killing hundreds and shaking the country.","Jallianwala Bagh"),
  ("The Non-Cooperation Movement began in 1920 with the Khilafat issue. People gave up titles, boycotted schools, courts and foreign cloth. It was called off after violence at Chauri Chaura in 1922.","Non-Cooperation 1920-22"),
  ("The Simon Commission of 1927 had no Indian members. In December 1929 the Lahore Congress under Jawaharlal Nehru demanded Purna Swaraj, complete independence.","Purna Swaraj 1929"),
  ("The Salt March began on 12 March 1930 from Sabarmati and reached Dandi on 6 April, where Gandhi broke the salt law. It launched the Civil Disobedience Movement.","Salt March 1930"),
  ("The Gandhi-Irwin Pact of 1931 ended the movement for a time. The Poona Pact of 1932 gave depressed classes reserved seats in provincial councils after the dispute with Ambedkar.","Pact 1931, Poona Pact 1932"),
  ("The sense of collective belonging grew through history, folklore, songs, the image of Bharat Mata and flags. Different groups understood freedom in their own ways.","sense of unity")],
 ("How many years passed between Jallianwala Bagh (1919) and the Salt March (1930)?",[("Subtract the years.","1930 minus 1919."),("1930 - 1919 = 11 years.","Check 1919 + 11 = 1930.")]),
 ("Describe the role of Gandhi's satyagraha in the freedom struggle.",["Truth and non-violence","Mass participation in Champaran, Rowlatt and Salt","Civil disobedience of unjust laws"],["Thinking satyagraha means passive weakness"]),
 ["WWI hardships and Rowlatt Act led to protests.","Jallianwala Bagh was in 1919.","Non-Cooperation (1920-22) and Civil Disobedience (1930) were mass movements.","Purna Swaraj was demanded at Lahore in 1929."],
 [mcq("h2-1",1,"Jallianwala Bagh massacre took place in","1919",[("1920","Non-Cooperation began in 1920."),("1930","Salt March year.")],"13 April 1919 in Amritsar."),
  tf("h2-2",1,"The Salt March ended at Dandi.",True,"Gandhi broke the salt law there."),
  mcq("h2-3",2,"The Non-Cooperation Movement was withdrawn after","Chauri Chaura",[("Dandi","Dandi was in 1930."),("Poona","The Poona Pact was in 1932.")],"A violent incident in Gorakhpur in 1922."),
  short("h2-4",2,"Who presided over the Lahore Congress of 1929?",["jawaharlal nehru","nehru"],"It declared Purna Swaraj.",[("gandhi","Gandhi did not preside.")]),
  mcq("h2-5",2,"Assertion (A): The Simon Commission was boycotted. Reason (R): It had no Indian members.",R,[("A true, R false","R is the reason."),("Both false","Both are correct.")],"Indians objected to an all-British commission."),
  mcq("h2-6",2,"The Poona Pact (1932) was between","Gandhi and Ambedkar",[("Gandhi and Irwin","That was the 1931 pact."),("Nehru and Jinnah","Not related.")],"It gave reserved seats to the depressed classes."),
  num("h2-7",3,"In which year was the Gandhi-Irwin Pact signed?",1931,"It followed the Civil Disobedience Movement.",[(1930,"1930 was the Salt March.")]),
  tf("h2-8",3,"Gandhi began Civil Disobedience by breaking the salt law.",True,"At Dandi on 6 April 1930.")])
# H3
C,CN='hist-the-making-of-a-global-world','History 3: The Making of a Global World'
B(C,CN,'the-making-of-a-global-world','The Making of a Global World',
 "A cup of tea from far away",
 "The tea in your cup, the potato on your plate and even your phone depend on trade that links continents. Today we trace how the world became connected.",
 [("Early trade linked Asia, Europe and Africa through the Silk Routes, which also carried ideas, religions and diseases.","Silk Routes"),
  ("After Europeans reached the Americas, food crops such as potato, maize and tomato spread across the world, and disease devastated the native peoples.","Columbian exchange"),
  ("In the nineteenth century the abolition of the Corn Laws in Britain in 1846 made food imports cheaper and shifted agriculture overseas.","Corn Laws 1846"),
  ("Rinderpest, a cattle plague, spread across Africa in the 1890s and destroyed cattle, which weakened local people and helped colonial control.","Rinderpest"),
  ("Indentured labour carried Indian workers to plantations in the Caribbean, Fiji and Mauritius under harsh contracts.","indentured labour"),
  ("The First World War and then the Great Depression from 1929 caused unemployment, falling prices and the collapse of banks.","Great Depression 1929"),
  ("In 1944 the Bretton Woods conference set up the International Monetary Fund and the World Bank to keep the economy stable.","Bretton Woods 1944"),
  ("After 1950s, former colonies formed the Group of 77 to demand a New International Economic Order, and later multinational companies spread across the world.","G-77 and MNCs")],
 ("A cargo of 600 sacks of grain is divided equally among 3 ships. How many sacks per ship?",[("Divide total by ships.","Equal share."),("600 / 3 = 200 sacks.","Check 3 x 200 = 600.")]),
 ("Explain how the Great Depression affected the world.",["Prices and incomes fell","Banks collapsed and unemployment rose","Trade fell sharply"],["Thinking it affected only the USA"]),
 ["The Silk Routes linked continents early.","Corn Laws and Rinderpest changed economies in the 19th century.","Great Depression began in 1929.","Bretton Woods created the IMF and World Bank."],
 [mcq("h3-1",1,"The IMF and World Bank were set up at","Bretton Woods",[("Vienna","Vienna 1815 dealt with Napoleon."),("Dandi","An Indian salt march site.")],"In 1944."),
  tf("h3-2",1,"Rinderpest was a cattle disease.",True,"It spread in Africa in the 1890s."),
  mcq("h3-3",2,"The Corn Laws in Britain were abolished in","1846",[("1929","Great Depression."),("1944","Bretton Woods.")],"Food imports became cheaper."),
  mcq("h3-4",2,"Assertion (A): Indentured labourers faced hard conditions. Reason (R): They were bound by contracts and often cheated.",R,[("A true, R false","R is true."),("Both false","Both are accurate.")],"The system was close to slavery in practice."),
  short("h3-5",2,"Name the trade routes that linked Asia with Europe and Africa.",["silk routes","silk route"],"Silk, spices and ideas travelled along them.",[("spice route","Related, but the chapter's name is Silk Routes.")]),
  num("h3-6",2,"In which year did the Great Depression begin?",1929,"Stock markets crashed in October 1929.",[(1939,"1939 is the start of WWII.")]),
  mcq("h3-7",3,"Which crops travelled from the Americas to the Old World?","Potato and maize",[("Wheat and rice","Already grown in Asia and Europe."),("Tea and coffee","Not from the Americas.")],"Potato transformed European diets."),
  tf("h3-8",3,"G-77 was a group of former colonies seeking a fair economic order.",True,"They demanded a New International Economic Order.")])
# H4
C,CN='hist-the-age-of-industrialisation','History 4: The Age of Industrialisation'
B(C,CN,'the-age-of-industrialisation','The Age of Industrialisation',
 "When machines met the village",
 "Before factories, weavers worked at home and merchants collected cloth. Then machines and steam changed work forever. We see how industries grew in Britain and in India.",
 [("Before factories, proto-industrialisation meant merchants gave raw material to peasant families who spun and wove at home, and then sold the cloth in the market.","proto-industrialisation"),
  ("In Britain, cotton mills of Richard Arkwright and the Spinning Jenny of James Hargreaves speeded up spinning, and James Watt improved the steam engine.","new machines"),
  ("Factories grew in Manchester and other towns. Workers faced long hours, low wages and unemployment, and women and children were employed.","factory life"),
  ("India's textile exports to Europe fell as Manchester cloth entered Indian markets. Weavers faced competition and the East India Company's control.","effect on Indian weavers"),
  ("The first cotton mill in Bombay came up in 1854, and mills grew in Ahmedabad and Madras. Jute mills were set up in Bengal.","Indian mills"),
  ("Jobbers recruited workers for factories and often controlled them, taking money from workers who wanted jobs.","jobbers"),
  ("Indian industrialists such as Dwarkanath Tagore and Jamsetji Tata invested in factories. Swadeshi in the 1900s pushed Indian-made goods.","Indian industrialists"),
  ("Advertisements, labels and calendars helped sell goods, using pictures of gods and national leaders to appeal to the public.","advertising")],
 ("A mill employs 120 workers and the number doubles after expansion. How many workers now?",[("Doubling means multiplying by 2.","Double of a number."),("120 x 2 = 240 workers.","Check by adding 120 + 120.")]),
 ("Describe the changes brought by industrialisation in India.",["Weavers lost markets","Mills in Bombay, Ahmedabad and Madras","Jobbers recruited labour"],["Thinking industrialisation helped all workers equally"]),
 ["Proto-industrialisation came before factories.","Machines changed spinning and power.","Indian mills grew from 1854.","Jobbers and advertising were part of the new economy."],
 [mcq("h4-1",1,"The first cotton mill in Bombay came up in","1854",[("1900","Too late."),("1800","Too early.")],"It began in 1854."),
  tf("h4-2",1,"Jobbers recruited workers for mills.",True,"They also controlled workers."),
  mcq("h4-3",2,"The Spinning Jenny was invented by","James Hargreaves",[("Richard Arkwright","He set up cotton mills."),("James Watt","He improved the steam engine.")],"It sped up spinning."),
  mcq("h4-4",2,"Assertion (A): Indian weavers faced decline. Reason (R): Cheap Manchester cloth flooded Indian markets.",R,[("A true, R false","R is correct."),("Both false","Both are correct.")],"British imports hurt handloom weavers."),
  short("h4-5",2,"What is the term for home-based production before factories?",["proto-industrialisation","proto industrialisation"],"Merchants supplied raw material to rural families.",[("mass production","That came with factories.")]),
  mcq("h4-6",3,"Who improved the steam engine?","James Watt",[("Hargreaves","Spinning Jenny inventor."),("Arkwright","Cotton mill owner.")],"Watt's improvements made steam engines widely useful."),
  tf("h4-7",3,"Advertisements used images of gods to sell goods.",True,"They appealed to a mass market."),
  short("h4-8",3,"Which Indian industrialist established steel works at Jamshedpur?",["jamsetji tata","jamsetji nusserwanji tata","tata"],"Tata's steel plant came up in Jamshedpur (additional, not in the textbook).",[("birla","Birla's industries were elsewhere.")])])
# H5
C,CN='hist-print-culture-and-the-modern-world','History 5: Print Culture and the Modern World'
B(C,CN,'print-culture-and-the-modern-world','Print Culture and the Modern World',
 "The book that changed a mind",
 "Imagine a world without books, newspapers or posters. Everything was copied by hand. Then printing arrived and ideas began to travel faster than ever.",
 [("Printing began in East Asia. Woodblock printing in China and Japan produced books and Marco Polo carried the technique to Italy.","Woodblock printing"),
  ("Around 1448 Johann Gutenberg developed the printing press in Strasbourg, with metal types. The first book he printed was the Bible.","Gutenberg"),
  ("Printing made books cheap and led to a reading public. It spread new ideas, such as Martin Luther's 95 Theses of 1517 which spurred the Protestant Reformation.","Luther 1517"),
  ("The Church tried to control print through an Index of Prohibited Books. The miller Menocchio was punished for his reading of the Bible.","Index and Menocchio"),
  ("In the eighteenth century novels and newspapers became popular. Penny chapbooks carried cheap tales and almanacs.","novels and newspapers"),
  ("In India, printing came with the Portuguese missionaries, and from the 1800s newspapers like the Bengal Gazette and Sambad Kaumudi appeared.","print in India"),
  ("The Vernacular Press Act of 1878 allowed the government to censor reports in Indian language papers.","Vernacular Press Act 1878"),
  ("Reformers and nationalists used print to spread ideas on caste, women and freedom. Women wrote and read, and cheap prints made visual culture popular.","print and reform")],
 ("A press prints 250 sheets in an hour. How many sheets in 8 hours?",[("Multiply rate by hours.","Same speed."),("250 x 8 = 2,000 sheets.","Check 250 x 4 = 1,000, then double it.")]),
 ("Explain how print helped spread new ideas.",["Books became cheap","More people could read","Ideas such as the Reformation spread"],["Thinking only the rich read printed books"]),
 ["Printing began in East Asia and Gutenberg developed the press around 1448.","Print spread ideas of reform and nationalism.","Authorities tried to control print.","The Vernacular Press Act was passed in 1878."],
 [mcq("h5-1",1,"The printing press with metal types was developed by","Gutenberg",[("Marco Polo","He carried woodblock printing to Italy."),("Luther","He used print for his ideas.")],"In Strasbourg around 1448."),
  tf("h5-2",1,"Martin Luther wrote the 95 Theses.",True,"They criticised practices of the Roman Catholic Church."),
  mcq("h5-3",2,"The Vernacular Press Act was passed in","1878",[("1857","Revolt year."),("1905","Swadeshi period.")],"It allowed censorship of Indian-language papers."),
  mcq("h5-4",2,"Assertion (A): Printing created a reading public. Reason (R): Books became cheaper and more widely available.",R,[("A true, R false","R explains A."),("Both false","Both are correct.")],"Cheap print reached more people."),
  short("h5-5",2,"Which printing method came first in China and Japan?",["woodblock","woodblock printing"],"Carved wooden blocks were inked and pressed.",[("movable metal type","This is Gutenberg's method.")]),
  mcq("h5-6",3,"The Index of Prohibited Books was kept by","the Roman Catholic Church",[("The East India Company","Not the Index."),("The Mughals","Not the Index.")],"The Church tried to control what was read."),
  tf("h5-7",3,"Novels helped create a new reading culture.",True,"Novels spread widely in the eighteenth century."),
  short("h5-8",3,"Name an early newspaper started by Raja Ram Mohan Roy.",["sambad kaumudi"],"It was a Bengali weekly (additional, not in the textbook).",[("bengal gazette","Bengal Gazette was started by Hicky.")])])
print('hist ok')
